package io.github.jesterportfolio.hearth.survival.housing;

import java.util.*;
import java.util.concurrent.*;
import java.nio.file.*;
import org.bukkit.*;
import org.bukkit.plugin.java.JavaPlugin;
import io.github.jesterportfolio.hearth.administration.RuntimeLease;
import io.github.jesterportfolio.hearth.survival.SurvivalWorlds;
import static io.github.jesterportfolio.hearth.survival.housing.HousingState.*;

/** 개인 월드는 소유 기록과 UUID/seed를 확인한 뒤 로드합니다. 언로드는 삭제가 아닙니다. */
public final class HousingWorlds {
 private final JavaPlugin plugin;private final UUID group,realm;private final Path directory;private final HousingSettings settings;private final HousingProtection protection;private final Executor owner;
 private final Map<UUID,org.bukkit.Chunk> tickets=new HashMap<>();private final Map<UUID,World> loaded=new HashMap<>();private final Map<UUID,Location> entries=new HashMap<>();private final Map<UUID,Long> idle=new HashMap<>();private final Map<UUID,CompletableFuture<World>> jobs=new HashMap<>();
 public HousingWorlds(JavaPlugin plugin,UUID group,UUID realm,HousingSettings settings,HousingProtection protection)throws Exception{this.plugin=plugin;this.group=group;this.realm=realm;this.settings=settings;this.protection=protection;owner=action->Bukkit.getScheduler().runTask(plugin,action);directory=plugin.getDataFolder().toPath().toAbsolutePath().resolve("housing-worlds");if(!Files.exists(directory))Files.createDirectory(directory);if(!directory.equals(directory.toRealPath()))throw new IllegalStateException("HOUSING_PATH");}
 public Optional<UUID> house(World w){return loaded.entrySet().stream().filter(e->e.getValue()==w).map(Map.Entry::getKey).findFirst();}public Collection<World> loaded(){return List.copyOf(loaded.values());}public boolean busy(){return !jobs.isEmpty();}
 private Path file(House h){return directory.resolve(h.id()+".properties");}
 private Properties read(House h)throws Exception{Path f=file(h);if(!f.equals(f.toRealPath())||!Files.isRegularFile(f,LinkOption.NOFOLLOW_LINKS)||Files.size(f)>4096||Files.exists(directory.resolve(h.id()+".pending")))throw new IllegalStateException("HOUSING_IDENTITY_HOLD");var p=new Properties();try(var r=Files.newBufferedReader(f)){p.load(r);}if(!group.toString().equals(p.getProperty("group"))||!realm.toString().equals(p.getProperty("realm"))||!h.id().toString().equals(p.getProperty("house"))||!h.world().toString().equals(p.getProperty("world"))||!Long.toString(h.seed()).equals(p.getProperty("seed")))throw new IllegalStateException("HOUSING_IDENTITY_MISMATCH");return p;}
 public CompletionStage<World> load(House h,Snapshot snapshot,boolean provision){if(jobs.containsKey(h.id()))return jobs.get(h.id());if(loaded.containsKey(h.id())){idle.put(h.id(),System.currentTimeMillis());return CompletableFuture.completedFuture(loaded.get(h.id()));}if(loaded.size()+jobs.size()>=settings.maxLoaded())return CompletableFuture.failedFuture(new IllegalStateException("HOUSING_WORLD_CAPACITY"));var result=new CompletableFuture<World>();jobs.put(h.id(),result);RuntimeLease.Lease lease=null;
  try{var key=Objects.requireNonNull(NamespacedKey.fromString(h.key()));var path=Bukkit.getServer().getLevelDirectory().toRealPath().resolve("dimensions").resolve(key.getNamespace()).resolve(key.getKey());for(Path q=path;q!=null&&!q.equals(Bukkit.getServer().getLevelDirectory().toRealPath());q=q.getParent())if(Files.isSymbolicLink(q))throw new IllegalStateException("HOUSING_WORLD_PATH");Properties saved=null;World w=Bukkit.getWorld(key);
   if(h.world()==null){if(!provision||h.phase()!=Phase.PREPARING||Files.exists(file(h),LinkOption.NOFOLLOW_LINKS)||Files.exists(path,LinkOption.NOFOLLOW_LINKS)||w!=null)throw new IllegalStateException("HOUSING_UNKNOWN_WORLD");lease=RuntimeLease.acquire(directory.resolve(h.id()+".pending"),"Hearth housing creation v1\n"+h.id()+"\n").orElseThrow();}
   else{saved=read(h);if(!path.equals(path.toRealPath())||!SurvivalWorlds.metadataUuid(path.resolve("data/paper/metadata.dat")).equals(h.world())||w!=null&&!w.getUID().equals(h.world()))throw new IllegalStateException("HOUSING_WORLD_MISMATCH");}
   if(w==null)w=Objects.requireNonNull(Bukkit.createWorld(WorldCreator.ofKey(key).environment(World.Environment.NORMAL).type(WorldType.FLAT).seed(h.seed())));if(w.getSeed()!=h.seed()||h.world()!=null&&!w.getUID().equals(h.world()))throw new IllegalStateException("HOUSING_WORLD_MISMATCH");final World world=w;final Properties recorded=saved;final RuntimeLease.Lease creation=lease;int cx=recorded==null?0:((int)Math.floor(Double.parseDouble(recorded.getProperty("x"))))>>4,cz=recorded==null?0:((int)Math.floor(Double.parseDouble(recorded.getProperty("z"))))>>4;
   world.getChunkAtAsync(cx,cz,h.world()==null).whenCompleteAsync((chunk,error)->{try{if(error!=null||chunk==null)throw new IllegalStateException("HOUSING_ENTRY_CHUNK");Location at=recorded==null?new Location(world,.5,world.getHighestBlockYAt(0,0)+1,.5):new Location(world,Double.parseDouble(recorded.getProperty("x")),Double.parseDouble(recorded.getProperty("y")),Double.parseDouble(recorded.getProperty("z")));if(!inside(h,at)||!SurvivalWorlds.safe(at))throw new IllegalStateException("HOUSING_ENTRY_UNSAFE");chunk.addPluginChunkTicket(plugin);tickets.put(h.id(),chunk);world.setSpawnLocation(at);loaded.put(h.id(),world);entries.put(h.id(),at);idle.put(h.id(),System.currentTimeMillis());if(creation!=null){world.save(true);var p=new Properties();p.setProperty("group",group.toString());p.setProperty("realm",realm.toString());p.setProperty("house",h.id().toString());p.setProperty("world",world.getUID().toString());p.setProperty("seed",Long.toString(h.seed()));coordinates(p,at);try(var out=Files.newBufferedWriter(file(h),StandardOpenOption.CREATE_NEW)){p.store(out,"Hearth private housing v1");}force(file(h));creation.clean();}jobs.remove(h.id());result.complete(world);}catch(Exception failure){jobs.remove(h.id());result.completeExceptionally(failure);}},owner);
  }catch(Exception e){jobs.remove(h.id());result.completeExceptionally(e);}return result;
 }
 private static void force(Path p)throws Exception{try(var ch=java.nio.channels.FileChannel.open(p,StandardOpenOption.WRITE)){ch.force(true);}}
 private static void coordinates(Properties p,Location at){p.setProperty("x",Double.toString(at.getX()));p.setProperty("y",Double.toString(at.getY()));p.setProperty("z",Double.toString(at.getZ()));}
 public static boolean inside(House h,Location at){double half=h.width()/2.0;return at.getX()>=-half&&at.getX()<half&&at.getZ()>=-half&&at.getZ()<half;}
 public Location entry(House h){var p=Objects.requireNonNull(entries.get(h.id())).clone();if(!inside(h,p)||!SurvivalWorlds.safe(p))throw new IllegalStateException("HOUSING_ENTRY_UNSAFE");return p;}
 public void setEntry(House h,Location at)throws Exception{if(loaded.get(h.id())!=at.getWorld()||!inside(h,at)||!SurvivalWorlds.safe(at))throw new IllegalStateException("HOUSING_ENTRY_UNSAFE");var p=read(h);coordinates(p,at);var tmp=directory.resolve(h.id()+".new."+UUID.randomUUID());try(var out=Files.newBufferedWriter(tmp,StandardOpenOption.CREATE_NEW)){p.store(out,"Hearth private housing v1");}force(tmp);Files.move(tmp,file(h),StandardCopyOption.ATOMIC_MOVE,StandardCopyOption.REPLACE_EXISTING);var chunk=at.getChunk();chunk.addPluginChunkTicket(plugin);var previous=tickets.put(h.id(),chunk);if(previous!=null&&(previous.getWorld()!=chunk.getWorld()||previous.getX()!=chunk.getX()||previous.getZ()!=chunk.getZ()))previous.removePluginChunkTicket(plugin);entries.put(h.id(),at.clone());at.getWorld().setSpawnLocation(at);}
 public CompletionStage<Void> apply(House h,Snapshot snapshot){var w=Objects.requireNonNull(loaded.get(h.id()));return protection.house(h,w,snapshot).thenRunAsync(()->w.save(true),owner);}
 public CompletionStage<Void> unload(UUID id){var w=loaded.get(id);if(w==null)return CompletableFuture.completedFuture(null);if(!w.getPlayers().isEmpty()||jobs.containsKey(id))return CompletableFuture.failedFuture(new IllegalStateException("HOUSING_WORLD_IN_USE"));w.save(true);var ticket=tickets.get(id);if(ticket!=null)ticket.removePluginChunkTicket(plugin);if(!Bukkit.unloadWorld(w,true)){if(ticket!=null)ticket.addPluginChunkTicket(plugin);return CompletableFuture.failedFuture(new IllegalStateException("HOUSING_UNLOAD_FAILED"));}tickets.remove(id);loaded.remove(id);entries.remove(id);idle.remove(id);return CompletableFuture.completedFuture(null);}
 public void tick(){for(var item:List.copyOf(loaded.entrySet())){if(!item.getValue().getPlayers().isEmpty())idle.put(item.getKey(),System.currentTimeMillis());else if(System.currentTimeMillis()-idle.get(item.getKey())>=settings.idleSeconds()*1000L&&!jobs.containsKey(item.getKey()))unload(item.getKey());}}
 public CompletionStage<Void> drain(){if(busy())return CompletableFuture.failedFuture(new IllegalStateException("HOUSING_WORLD_BUSY"));CompletionStage<Void> work=CompletableFuture.completedFuture(null);for(var id:List.copyOf(loaded.keySet()))work=work.thenComposeAsync(v->unload(id),owner);return work;}
}
